import SwiftUI
import WebKit
import UIKit

// MARK: - Color Namespace

extension Color {
    static let gjuha = GjuhaColors()
}

/// Semantic colour roles for Gjuha.
///
/// Every token is a Named Color in `Palette.xcassets` with four appearances
/// (light, dark, and the increased-contrast variant of each), generated by
/// `Scripts/gen_colors.py`. That script measures every foreground/background
/// pair it ships and refuses to write a set that falls below 4.5:1, so a token
/// used in its documented role is legible by construction.
///
/// Two role distinctions matter when picking one:
///
/// - **Fill vs on-surface text.** `accent`, `success`, `error`, `warning`,
///   `streak` and `xp` are *fills*: a shape behind a foreground. The matching
///   `…Strong` token is the one to use for text or an icon drawn *on* a surface.
///   Gold text on `surface` measures 1.76:1; `xpStrong` measures 5.24:1.
/// - **What goes on a fill.** `onAccent` (white) for `accent`, `streak`,
///   `success` and `error`. `onWarning` (near-black) for `warning` and `xp`,
///   which stay bright rather than being deepened into brown.
struct GjuhaColors {
    // MARK: Brand

    /// Primary action fill. Carries ``onAccent``.
    let accent = Color("Accent")
    /// Accent as text or an icon on a surface.
    let accentStrong = Color("AccentStrong")
    /// Light tint of the accent, for selected rows and soft backgrounds.
    let accentSubtle = Color("AccentSubtle")

    // MARK: Background hierarchy

    let background = Color("Background")
    let surface = Color("Surface")
    let surfaceSecondary = Color("SurfaceSecondary")

    // MARK: Text

    let textPrimary = Color("TextPrimary")
    let textSecondary = Color("TextSecondary")
    let textTertiary = Color("TextTertiary")

    // MARK: State

    /// Success fill. Carries ``onAccent``.
    let success = Color("Success")
    /// Success as text or an icon on a surface.
    let successStrong = Color("SuccessStrong")
    /// Warning fill, deliberately bright. Carries ``onWarning``.
    let warning = Color("Warning")
    /// Warning as text or an icon on a surface.
    let warningStrong = Color("WarningStrong")
    /// Error fill. Carries ``onAccent``.
    let error = Color("Error")
    /// Error as text or an icon on a surface.
    let errorStrong = Color("ErrorStrong")

    // MARK: Gamification

    /// Streak fill. Carries ``onAccent``.
    let streak = Color("Streak")
    /// Streak as text or an icon on a surface, such as the flame and its count.
    let streakStrong = Color("StreakStrong")
    /// XP fill, deliberately bright gold. Carries ``onWarning``.
    let xp = Color("XP")
    /// XP as text or an icon on a surface, such as the star and its count.
    let xpStrong = Color("XPStrong")

    // MARK: Separators, edges and overlay fills

    /// Opaque divider and control border.
    let border = Color("Border")
    /// The edge of a glass card or a tappable surface. Inverts with the
    /// appearance, so unlike a hardcoded white overlay it stays visible in
    /// light mode.
    let hairline = Color("Hairline")
    /// The tint laid over a material inside a glass card.
    let glassTint = Color("GlassTint")
    /// The unfilled part of a progress bar, ring or meter.
    let track = Color("Track")
    /// Background of a small capsule chip.
    let chipFill = Color("ChipFill")
    /// Background of an unselected, tappable option row.
    let controlFill = Color("ControlFill")

    // MARK: Foreground on a fill

    /// Foreground on ``accent``, ``streak``, ``success`` and ``error``.
    let onAccent = Color("OnAccent")
    /// Foreground on ``warning`` and ``xp``.
    let onWarning = Color("OnWarning")
}

// MARK: - Fallback Color Literals (for previews without asset catalog)

extension Color {
    static var gjuhaAccentFallback: Color { Color(red: 0.87, green: 0.26, blue: 0.21) }
    static var gjuhaBackgroundFallback: Color { Color(UIColor.systemBackground) }
    static var gjuhaSurfaceFallback: Color { Color(UIColor.secondarySystemBackground) }
}

// MARK: - Liquid Glass Styling

private struct GjuhaLiquidGlassCardModifier: ViewModifier {
    /// The tint opacity the call sites were written against, back when the tint
    /// was flat white. Dividing by it turns each existing `tintOpacity:` value
    /// into a multiplier on `glassTint`, so every card keeps its relative
    /// weight without touching ~20 call sites.
    static let referenceTint: Double = 0.08

    let cornerRadius: CGFloat
    let tintOpacity: Double

    func body(content: Content) -> some View {
        content
            .background(
                RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
                    .fill(.ultraThinMaterial)
                    .overlay(
                        RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
                            // `glassTint` carries its own per-appearance alpha, so
                            // `tintOpacity` scales it rather than replacing it. The
                            // old code tinted with flat white, which in light
                            // appearance tinted a white surface with white.
                            .fill(Color.gjuha.glassTint.opacity(tintOpacity / Self.referenceTint))
                    )
            )
            .overlay(
                RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
                    // The edge was `Color.white.opacity(0.24)`: invisible against
                    // the near-white light background, so cards had no boundary.
                    .stroke(Color.gjuha.hairline, lineWidth: 0.8)
            )
            .shadow(color: .black.opacity(0.14), radius: 14, y: 8)
    }
}

struct GjuhaLiquidGlassBackground: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var drift = false

    var body: some View {
        ZStack {
            LinearGradient(
                colors: [
                    Color.gjuha.background,
                    Color.gjuha.accentSubtle.opacity(0.45),
                    Color.gjuha.background
                ],
                startPoint: drift ? .topLeading : .bottomTrailing,
                endPoint: drift ? .bottomTrailing : .topLeading
            )
            .animation(
                reduceMotion
                ? .linear(duration: 0.01)
                : .easeInOut(duration: 6.4).repeatForever(autoreverses: true),
                value: drift
            )

            Circle()
                .fill(Color.gjuha.glassTint.opacity(0.5))
                .frame(width: 300, height: 300)
                .blur(radius: 14)
                .offset(x: drift ? -165 : -110, y: drift ? -250 : -210)
                .animation(
                    reduceMotion
                    ? .linear(duration: 0.01)
                    : .easeInOut(duration: 5.2).repeatForever(autoreverses: true),
                    value: drift
                )

            Circle()
                .fill(Color.gjuha.accent.opacity(0.12))
                .frame(width: 260, height: 260)
                .blur(radius: 20)
                .offset(x: drift ? 175 : 130, y: drift ? 240 : 290)
                .animation(
                    reduceMotion
                    ? .linear(duration: 0.01)
                    : .easeInOut(duration: 5.8).repeatForever(autoreverses: true),
                    value: drift
                )

            RoundedRectangle(cornerRadius: 52, style: .continuous)
                .fill(Color.gjuha.glassTint.opacity(0.28))
                .frame(width: 220, height: 220)
                .blur(radius: 20)
                .rotationEffect(.degrees(drift ? 18 : -12))
                .offset(x: drift ? 150 : 205, y: drift ? -250 : -210)
                .animation(
                    reduceMotion
                    ? .linear(duration: 0.01)
                    : .easeInOut(duration: 7.2).repeatForever(autoreverses: true),
                    value: drift
                )
        }
        .ignoresSafeArea()
        .onAppear {
            if reduceMotion { return }
            drift = true
        }
    }
}

extension View {
    func gjuhaLiquidGlassCard(cornerRadius: CGFloat = 16, tintOpacity: Double = 0.08) -> some View {
        modifier(GjuhaLiquidGlassCardModifier(cornerRadius: cornerRadius, tintOpacity: tintOpacity))
    }

    /// Constrains content to a comfortable single column reading width and centers
    /// it, so wide screens (iPad, landscape) do not stretch the single column
    /// learning UI edge to edge. On iPhone the cap is wider than the screen, so it is
    /// a no op. Apply to a screen's content, never to its full bleed background.
    func gjuhaReadableWidth(_ maxWidth: CGFloat = 620) -> some View {
        frame(maxWidth: maxWidth)
            .frame(maxWidth: .infinity)
    }
}

struct AnimatedMascotView: View {
    let size: CGFloat
    let usesGlassOrb: Bool

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var float = false

    init(size: CGFloat, usesGlassOrb: Bool = true) {
        self.size = size
        self.usesGlassOrb = usesGlassOrb
    }

    private var gifData: Data? {
        NSDataAsset(name: "MascotLoop")?.data
    }

    var body: some View {
        ZStack {
            if usesGlassOrb {
                Circle()
                    .fill(Color.gjuha.accent.opacity(0.2))
                    .frame(width: size + 8, height: size + 8)
                    .blur(radius: 12)

                Circle()
                    .fill(.ultraThinMaterial)
                    .frame(width: size, height: size)
                    .overlay(
                        Circle()
                            .stroke(Color.gjuha.hairline, lineWidth: 0.8)
                    )
            }

            // Reduce Motion falls through to the still mascot below. Gating only
            // the fallback image, as this did before, left the looping animation
            // playing for exactly the people who asked for less motion.
            if let gifData, !reduceMotion {
                TransparentAnimatedGIFView(data: gifData)
                    .frame(width: usesGlassOrb ? size - 14 : size, height: usesGlassOrb ? size - 14 : size)
                    .clipShape(Circle())
            } else {
                Image("MascotIcon")
                    .resizable()
                    .scaledToFit()
                    .frame(width: usesGlassOrb ? size - 16 : size, height: usesGlassOrb ? size - 16 : size)
                    .scaleEffect(float ? 1.03 : 0.94)
                    .rotationEffect(.degrees(float ? -1.8 : 1.8))
                    .offset(y: float ? -2 : 3)
                    .animation(
                        reduceMotion
                        ? .linear(duration: 0.01)
                        : .easeInOut(duration: 1.1).repeatForever(autoreverses: true),
                        value: float
                    )
            }
        }
        .onAppear {
            if reduceMotion { return }
            float = true
        }
    }
}

private struct TransparentAnimatedGIFView: UIViewRepresentable {
    let data: Data

    func makeCoordinator() -> Coordinator {
        Coordinator()
    }

    func makeUIView(context: Context) -> WKWebView {
        let configuration = WKWebViewConfiguration()
        configuration.allowsInlineMediaPlayback = true

        let webView = WKWebView(frame: .zero, configuration: configuration)
        webView.isOpaque = false
        webView.backgroundColor = .clear
        webView.scrollView.backgroundColor = .clear
        webView.scrollView.isScrollEnabled = false
        webView.isUserInteractionEnabled = false
        return webView
    }

    func updateUIView(_ webView: WKWebView, context: Context) {
        let fingerprint = data.hashValue
        guard context.coordinator.loadedFingerprint != fingerprint else { return }
        context.coordinator.loadedFingerprint = fingerprint

        let base64 = data.base64EncodedString()
        let html = """
        <html>
        <head>
        <meta name="viewport" content="initial-scale=1.0, maximum-scale=1.0">
        <style>
        html, body { margin: 0; padding: 0; background: transparent; overflow: hidden; }
        img { width: 100%; height: 100%; object-fit: contain; background: transparent; }
        </style>
        </head>
        <body>
        <img src="data:image/gif;base64,\(base64)" />
        </body>
        </html>
        """

        webView.loadHTMLString(html, baseURL: nil)
    }

    final class Coordinator {
        var loadedFingerprint: Int?
    }
}
